Step 0.4: See it for yourself
A toy example: 120 sites where ⁸⁷Sr/⁸⁶Sr rises with distance from the coast (less sea-salt Sr) and jumps at 260 km where the bedrock changes. Move the sliders.






The sliders only work on this website, not in RStudio.




viewof ntree = Inputs.range([1, 200], {value: 1, step: 1, label: "Number of trees"})
viewof depth = Inputs.range([1, 10], {value: 8, step: 1, label: "Maximum tree depth"})
viewof showTrees = Inputs.toggle({label: "Show the individual trees", value: true})























rf = {
  const mulberry32 = a =&gt; function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a&gt;&gt;&gt;15,1|a);t=t+Math.imul(t^t&gt;&gt;&gt;7,61|t)^t;return((t^t&gt;&gt;&gt;14)&gt;&gt;&gt;0)/4294967296}
  const gauss = r =&gt; {let u=0,v=0;while(u===0)u=r();while(v===0)v=r();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
  const truth = x =&gt; 0.7092 + 0.009*(1-Math.exp(-x/60)) + (x&gt;260 ? 0.006 : 0)
  const r0 = mulberry32(42)
  const sites = Array.from({length:120}, () =&gt; { const x = 10 + r0()*380; return {x, y: truth(x) + 0.0015*gauss(r0)} })
  function buildTree(pts, d, minLeaf){
    const mean = pts.reduce((s,p)=&gt;s+p.y,0)/pts.length
    if (d===0 || pts.length &lt; 2*minLeaf) return {leaf:true, value:mean}
    const s = [...pts].sort((a,b)=&gt;a.x-b.x)
    let best=null, bestSSE=Infinity, sumL=0, sqL=0
    const tot=s.reduce((a,p)=&gt;a+p.y,0), totSq=s.reduce((a,p)=&gt;a+p.y*p.y,0)
    for (let i=0;i&lt;s.length-1;i++){
      sumL+=s[i].y; sqL+=s[i].y*s[i].y
      const nL=i+1, nR=s.length-nL
      if (nL&lt;minLeaf || nR&lt;minLeaf || s[i].x===s[i+1].x) continue
      const sse=(sqL-sumL*sumL/nL)+((totSq-sqL)-(tot-sumL)**2/nR)
      if (sse&lt;bestSSE){bestSSE=sse; best=(s[i].x+s[i+1].x)/2}
    }
    if (best===null) return {leaf:true, value:mean}
    return {leaf:false, t:best, left:buildTree(s.filter(p=&gt;p.x&lt;=best),d-1,minLeaf), right:buildTree(s.filter(p=&gt;p.x&gt;best),d-1,minLeaf)}
  }
  function predict(n, x){ return n.leaf ? n.value : predict(x&lt;=n.t ? n.left : n.right, x) }
  function grow(ntree, depth){
    return Array.from({length:ntree}, (_,k) =&gt; { const r=mulberry32(1000+k); return buildTree(Array.from({length:sites.length}, () =&gt; sites[Math.floor(r()*sites.length)]), depth, 3) })
  }
  return {sites, truth, predict, grow}
}
grid = Array.from({length:201}, (_,i)=&gt;i*2)
trees = rf.grow(ntree, depth)
forestLine = grid.map(x =&gt; ({x, y: trees.reduce((s,t)=&gt;s+rf.predict(t,x),0)/trees.length}))
treeLines = showTrees ? trees.slice(0,30).flatMap((t,k) =&gt; grid.map(x =&gt; ({x, y: rf.predict(t,x), tree:k}))) : []
truthLine = grid.map(x =&gt; ({x, y: rf.truth(x)}))
rmse = Math.sqrt(grid.reduce((s,x,i)=&gt;s+(forestLine[i].y-rf.truth(x))**2,0)/grid.length)

md`**${ntree === 1 ? "One tree" : ntree + " trees"}**, depth ${depth} · error against the true curve (RMSE) = **${rmse.toFixed(4)}**`
























































Plot.plot({
  height: 360, marginLeft: 60,
  x: {label: "Distance to the coast (km)", domain: [0, 400]},
  y: {label: "⁸⁷Sr/⁸⁶Sr", tickFormat: d =&gt; d.toFixed(3), grid: true},
  marks: [
    Plot.dot(rf.sites, {x: "x", y: "y", fill: "#9aa5ad", r: 2.5}),
    Plot.line(truthLine, {x: "x", y: "y", stroke: "#333", strokeDasharray: "4,4"}),
    Plot.line(treeLines, {x: "x", y: "y", z: "tree", stroke: "#8a3b12", strokeOpacity: 0.25, curve: "step"}),
    Plot.line(forestLine, {x: "x", y: "y", stroke: "#1f4e6b", strokeWidth: 2.5, curve: "step"})
  ]
})








Grey dots: training sites. Dashed: the true relationship. Thin orange: individual trees (up to 30 shown). Blue: the prediction (the average of all trees).






🧩 Your turn




With 1 tree and depth 8, how does the prediction look? Does it follow the noise or the true curve?
Increase the number of trees to 50, then 200. What happens to the blue line and to the RMSE?
With 200 trees, set the depth to 1, then 2, then 4. What goes wrong when the trees are too shallow?









Things you might have noticed






One deep tree is a staircase that chases individual sites: it overfits the noise.
Averaging many trees smooths the staircase and brings the prediction closer to the true curve: the RMSE drops. Beyond ~50 trees it barely changes, which is why a few hundred trees are enough.
Very shallow trees can’t capture the shape (a depth-1 tree has only one step): the forest underfits. Random forests usually grow deep trees and let averaging remove the noise.

Notice also the edges: beyond the last site (here near 0 and 390 km), the prediction is flat. A random forest cannot extrapolate beyond the range of its training data.
